from playwright.sync_api import sync_playwright
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
html=(root/'technology-preview.html').read_text(encoding='utf-8')
html=html.replace('<link rel="stylesheet" href="data/technology-ui.css">','<style>'+(root/'data/technology-ui.css').read_text(encoding='utf-8')+'</style>')
for n in ['data','locales','core','ui']:
    html=html.replace('<script src="data/technology-'+n+'.js"></script>','<script>'+(root/('data/technology-'+n+'.js')).read_text(encoding='utf-8')+'</script>')
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 page=browser.new_page(viewport={'width':390,'height':844},device_scale_factor=1)
 errors=[];page.on('pageerror',lambda e: errors.append(str(e)))
 page.set_content(html.replace('<script>','<script>Object.defineProperty(window,"localStorage",{value:(()=>{const m=new Map();return {getItem:k=>m.get(k)??null,setItem:(k,v)=>m.set(k,v),clear:()=>m.clear()}})()});',1));page.wait_for_selector('.tech-card')
 res=page.evaluate('''()=>{let checks=0;const ck=(b,m)=>{if(!b)throw Error(m);checks++};const eq=(a,b)=>{const k=x=>JSON.stringify(Object.entries(x).sort());return k(a)===k(b)};let intervals=0;for(const item of technologyData){for(let a=0;a<=item.rows.length;a++){for(let b=a;b<=item.rows.length;b++){const c=TechnologyCore.calc(item,a,b,100),rs=item.rows.slice(a,b),cost={};let time=0,xp=0;for(const r of rs){for(const x of r.cost||[])cost[x.t]=(cost[x.t]||0)+x.c;time+=r.tm||0;xp+=r.xp||0}ck(eq(cost,c.costs),'cost '+item.id);ck(c.time===time&&c.adjusted===Math.ceil(time/2),'time '+item.id);ck(c.xp===xp,'xp '+item.id);ck(c.rows.length===b-a,'range '+item.id);intervals++} }const max=item.rows.length;const plan=TechnologyCore.plan({[item.id]:[0,max]},item.group,0,true);ck(plan.selected.some(x=>x.id===item.id&&x.to===max),'plan '+item.id);ck(Object.keys(plan.requires).length===0,'requirements '+item.id)}for(const lang of techLanguages){for(const item of technologyData){ck(techName(item,lang)&& (lang==='en'||techNames[item.base]?.[lang]),'name '+lang+' '+item.id);const id=item.rows[0].eg||item.rows[0].eid||item.rows[0].eff?.t;if(id){const v=technologyEffectNames[id];ck(!!techEffectName(id,lang),'effect '+lang+' '+id);ck(lang==='en'||!!(techEffectTranslations[v]?.[lang]??techNames[techEffectAliases[v]??v]?.[lang]??techNames[techSkillEffectById[id]]?.[lang]),'effect translation '+lang+' '+v)}}}return {checks,intervals,items:technologyData.length,icons:Object.keys(technologyArt).length}}''')
 print('CORE',res)
 result=page.evaluate('''()=>{let checks=0;const ck=(b,m)=>{if(!b)throw Error(m);checks++};const root=document.querySelector('#technologyRoot'),lang=document.querySelector('#language');const clean=()=>!(/\\b(?:undefined|NaN|Infinity)\\b/.test(root.textContent));for(const l of techLanguages){lang.value=l;lang.onchange();for(const [g,n] of [['academy',93],['garage',9],['alliance',25],['allianceAcademy',12]]){tech.go('catalog');const tabs=[...root.querySelectorAll('.tech-tabs button')];tabs[['academy','garage','alliance','allianceAcademy'].indexOf(g)].click();ck(root.querySelectorAll('[data-tech-id]').length===n,l+' '+g+' count');for(const item of technologyData.filter(x=>x.group===g)){tech.go('detail',item.id);const selects=root.querySelectorAll('.tech-fields select');ck(selects.length===2,l+' '+item.id+' selects');selects[1].value=String(item.rows.length);selects[1].onchange();ck(clean(),l+' '+item.id+' clean');ck(selects[1].options.length===item.rows.length+1,l+' '+item.id+' levels');const img=root.querySelector('.tech-profile img');ck(!!img===!!item.icon,l+' '+item.id+' art');selects[0].value=String(item.rows.length);selects[0].onchange();ck(clean(),l+' '+item.id+' max');selects[0].value='0';selects[0].onchange();}tech.go('plan');ck(clean(),l+' '+g+' plan');tech.go('catalog');const q=root.querySelector('input[type=search]');q.value='zzzzz-no-match';q.oninput();ck(root.querySelectorAll('[data-tech-id]').length===0,l+' '+g+' search');q.value='';q.oninput();}}return {checks,locales:techLanguages.length}}''')
 print('UI',result, 'errors',errors)
 cases=page.evaluate('''()=>{const C=TechnologyCore,oil=C.byId.get(83886085),hp=C.byId.get(83886296),shield=C.byId.get(83886394);let o=C.calc(oil,6,7),h=C.calc(hp,20,21),s=C.calc(shield,0,1);if(o.costs[67174409]!==96256||o.before.value!==90||o.after.value!==105||o.buildings[16842759]!==7||o.requires[83886086]!==1||h.xp!==343560||h.before.value!==100||h.after.value!==105||C.remainingXp(hp,20,21,87360)!==256200||h.rows[0].sdr!==3400||h.rows[0].sdm!==42||s.xp!==1000||s.after.value!==30||C.remainingXp(shield,0,1,847)!==153)throw Error('Screenshot verification');if(technologyData.some(i=>!technologyArt[i.icon]))throw Error('Missing art');return {screenshotCases:3,art:technologyData.length}}''')
 print('GAME',cases)
 assert not errors
 assert page.evaluate('''()=>{const r=TechnologyUI.install(document.createElement('div'),()=> 'ru');const item=technologyData[0];return r.getState()[item.id]?.[1]===item.rows.length}''')
 page=browser.new_page(viewport={'width':390,'height':844},device_scale_factor=1);page.set_content(html)
 page.wait_for_selector('.tech-card');page.screenshot(path=str(Path(__file__).with_name('catalog-preview.png')),full_page=False);page.locator('[data-tech-id="83886082"]').click();page.locator('.tech-fields select').nth(1).select_option('10');page.screenshot(path=str(Path(__file__).with_name('calculator-preview.png')),full_page=True);browser.close()
